import sys; sys.path.insert(0,'.'); from lib import *
from scipy.special import erf
gelu=lambda t: 0.5*t*(1+erf(t/np.sqrt(2)))
d=load_base(); y=labels(); M0=d['mean_hidden_L0']
def cosnorm(X, mu=None):
    Z=X-(X.mean(0) if mu is None else mu); Z=Z-Z.mean(1,keepdims=True); return Z/np.linalg.norm(Z,axis=1,keepdims=True)
def kern(Z1,Z2,a=1.0): S=Z1@Z2.T; return S+(gelu(a*S)+gelu(-a*S))/(a*a)
def nb(x): x=x-x.mean(0); return x/np.sqrt((x**2).sum(1).mean())
def nested_cv(X, y, w, k=10, seeds=(0,1,2), lam_r=3.0, lam_k=0.03, ndir='ridge', orth=False):
    accs=[]; X=nb(X)
    for s in seeds:
        f=folds(y,k,s); P=np.zeros(len(y),int)
        for i in range(k):
            tr=f!=i; te=f==i
            Wr,_=ridge_fit(X[tr],y[tr],lam_r)
            if orth: Qd,_=np.linalg.qr(Wr); proj=X@Qd
            else: proj=X@Wr
            sc=np.sqrt(((proj[tr]-proj[tr].mean(0))**2).sum(1).mean())
            F=np.concatenate([X, w*(proj-proj[tr].mean(0))/sc],1)
            Z=cosnorm(F, F[tr].mean(0))
            K=kern(Z[tr],Z[tr]); Y=np.eye(8)[y[tr]]
            A=np.linalg.solve(K+lam_k*np.eye(tr.sum()),Y-Y.mean(0)); P[te]=(kern(Z[te],Z[tr])@A).argmax(1)
        accs.append((P==y).mean())
    return round(float(np.mean(accs)),4)
